using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        ref int start = ref MemoryMarshal.GetReference(data);
        int length = data.Length;
        int i = 0;

        if (Vector512.IsHardwareAccelerated && length >= Vector512<int>.Count)
        {
            var vThreshold = Vector512.Create(threshold);
            var vOne = Vector512.Create(1);
            int lastVector = length - Vector512<int>.Count;
            for (; i <= lastVector; i += Vector512<int>.Count)
            {
                ref int pos = ref Unsafe.Add(ref start, i);
                var vec = Vector512.LoadUnsafe(ref pos);
                var mask = Vector512.GreaterThan(vec, vThreshold);
                vec += vOne & mask;
                Vector512.StoreUnsafe(vec, ref pos);
            }
        }
        else if (Vector256.IsHardwareAccelerated && length >= Vector256<int>.Count)
        {
            var vThreshold = Vector256.Create(threshold);
            var vOne = Vector256.Create(1);
            int lastVector = length - Vector256<int>.Count;
            for (; i <= lastVector; i += Vector256<int>.Count)
            {
                ref int pos = ref Unsafe.Add(ref start, i);
                var vec = Vector256.LoadUnsafe(ref pos);
                var mask = Vector256.GreaterThan(vec, vThreshold);
                vec += vOne & mask;
                Vector256.StoreUnsafe(vec, ref pos);
            }
        }
        else if (Vector128.IsHardwareAccelerated && length >= Vector128<int>.Count)
        {
            var vThreshold = Vector128.Create(threshold);
            var vOne = Vector128.Create(1);
            int lastVector = length - Vector128<int>.Count;
            for (; i <= lastVector; i += Vector128<int>.Count)
            {
                ref int pos = ref Unsafe.Add(ref start, i);
                var vec = Vector128.LoadUnsafe(ref pos);
                var mask = Vector128.GreaterThan(vec, vThreshold);
                vec += vOne & mask;
                Vector128.StoreUnsafe(vec, ref pos);
            }
        }

        // Scalar tail
        for (; i < length; i++)
        {
            ref int val = ref Unsafe.Add(ref start, i);
            if (val > threshold)
                val++;
        }
    }
}

